  ('dea-typ-is-richtig-leiwaund-mit-dem-kaunnst-reedn-lochn-saufn-ollas', 'Dea Typ is richtig leiwaund - mit dem kaunnst reedn, lochn, saufn, ollas!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Typ is richtig leiwand – mit dem kannst reden, lachen, saufen, alles!', '[{"kategorie": "wörtlich", "text": "\"Der Kerl ist echt cool – mit dem kannst reden, lachen, saufen, alles!\"  2. Das ist ein richtig entspannter Typ – mit dem kannst du Pferde stehlen!  3. Der Kerl ist total locker drauf – mit dem wird’s nie fad!"}]'::jsonb, ''),
  ('sei-leiwaundsei-is-nua-aungauswischarei', 'Sei Leiwaundsei is nua Aungauswischarei!', '', '', '', '', 'Sein Leinwandsein ist nur Augenauswischerei', '[{"kategorie": "", "text": "Seine Lässigkeit ist bloß Augenauswischerei!  2. Seine Liebenswürdigkeit ist nur gespielt!"}]'::jsonb, ''),
  ('wem-auf-leiwaund-haum', 'wem auf leiwaund haum', '', '', '', '', 'jemanden auf leiwand haben', '[{"kategorie": "wörtlich", "text": "\"jemanden wie auf einer schneeweißen Leinwand haben\""}, {"kategorie": "fig.", "text": "sich jemandes sicher sein, jemanden in die Tasche stecken, jemanden im Griff haben, jemandem deutlich überlegen sein"}, {"kategorie": "scherzhaft für", "text": "jemanden necken, hänseln, frotzeln, verspotten, [[häkerln]]"}]'::jsonb, ''),
  ('de-haumma-garantiad-auf-leiwaund', 'De haumma garantiad auf leiwaund!', '', '', '', '', 'Die haben wir garantiert auf leiwand!', '[{"kategorie": "wörtlich", "text": "\"Die haben wir garantiert wie auf einer schneeweißen Leinwand!\"  2. (fig.) Die stecken wir garantiert in die Tasche!  3. Denen sind wir garantiert überlegen!  4. Die haben wir garantiert im Griff!"}]'::jsonb, ''),
  ('augsburga-mit-erdaepfln-und-raamfisoin', 'Augsburga mit Erdäpfln und Raamfisoin', '', '', '', '', 'Augsburger mit Erdäpfeln und Rahmfisolen', '[{"kategorie": "", "text": "traditionelles Gericht der Wiener Küche"}, {"kategorie": "Deutschland", "text": "geräucherte Schweinbrühwurst mit Kartoffeln und grünen Bohnen in Sahnesauce"}]'::jsonb, ''),
  ('es-is-aus-und-gschehn', 'Es is aus und gschehn!', '', '', '', '', 'Es ist aus und geschehen', '[{"kategorie": "", "text": "Es ist alles vorbei!  2. Alles ist aus und nicht mehr zu ändern!"}]'::jsonb, ''),
  ('loss-mi-no-a-wengl-ausbaatzn', 'Loss mi no a wengl ausbaatzn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Lass mich noch ein wenig ausbatzen!', '[{"kategorie": "wörtlich", "text": "\"Lass mich noch ein wenig ausruhen!\"  2. Lass mich noch ein bisschen dösen!  3. Gib mir noch einen Moment zum Wachwerden!"}]'::jsonb, ''),
  ('loss-mi-no-a-wengl-ausbotzn', 'Loss mi no a wengl ausbotzn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Lass mich noch ein wenig ausbeizen!', '[{"kategorie": "wörtlich", "text": "\"Lass mich noch ein wenig ausruhen!\"  2. Lass mich noch ein bisschen dösen!  3. Gib mir noch einen Moment zum Wachwerden!"}]'::jsonb, ''),
