  ('au-schiach', 'Au schiach!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Au schirch!', '[{"kategorie": "wörtlich", "text": "\"Oh wie abgrundtief hässlich!\" (spontaner, schockierter Ausruf beim Anblick von etwas besonders abstoßend Hässlichem)"}, {"kategorie": "", "text": "Oh Gott, wie hässlich!  3. Au, das brennt in der Netzhaut!  4. [[Jo, leck, is des schiach!]]"}]'::jsonb, ''),
  ('jo-leck-is-des-schiach', 'Jo, leck, is des schiach!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ja, leck, ist das schirch!', '[{"kategorie": "wörtlich", "text": "\"Ja, leck mich am Arsch, ist das hässlich!\" (spontaner, schockierter Ausruf beim Anblick von etwas besonders abstoßend Hässlichem)"}, {"kategorie": "", "text": "Oh Gott, wie hässlich!  3. Au, das brennt in der Netzhaut!  4. [[Au, schiach!]]"}]'::jsonb, 'Au schiach!'),
