  ('an-brachoida-ausfoarhn', 'an Brachoida ausfoarhn', '', '', '', '', 'einen Bracholder ausfahren', '[{"kategorie": "", "text": "zum Faustschlag ausholen"}, {"kategorie": "", "text": "zum Faustschlag ansetzen"}]'::jsonb, ''),
  ('loss-di-ned-ollawaeu-so-ausfratschln', 'Loss di ned ollawäu so ausfratschln!', '', '', '', '', 'Lass dich nicht immerzu so ausfratscheln!', '[{"kategorie": "", "text": "Lass dich nicht immerzu so aushorchen!"}, {"kategorie": "", "text": "Lass dir nicht immerzu jedes Wort entlocken!  3. Plauder nicht alles aus!  4. Lass dich nicht zum Tratschtascherl machen!"}]'::jsonb, ''),
  ('du-host-bei-mia-ausgschissn', 'Du host bei mia ausgschissn!', '', '', '', '', 'Du hast bei mir ausgeschissen!', '[{"kategorie": "", "text": "Du hast bei mir ausgespielt!  2. Ich bin mit dir fertig!"}]'::jsonb, ''),
  ('ausgschdeckd-is', 'Ausgschdeckd is!', '', '', '', '', 'Ausgesteckt ist!', '[{"kategorie": "wörtlich", "text": "\"Der Reisigbusch ist ausgesteckt!\"  2. Es wird ausgeschenkt!  3. Es ist geöffnet! (bezieht sich auf die Sitte, einen Zweig oder einen „Buschen“ [meist aus Föhrenzweigen oder Reisig] vor dem Eingang des Lokals aufzuhängen, um solcherart anzuzeigen, dass das Lokal geöffnet ist)"}]'::jsonb, ''),
  ('dem-haengt-da-dalles-ausse', 'Dem hängt da Dalles ausse!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Dem hängt der Dalles raus!', '[{"kategorie": "wörtlich", "text": "\"Dem steht das Elend ins Gesicht geschrieben!\"  2. Ihm ist seine Not schon von Weitem anzusehen!  3. Dem merkt man die Pleite schon von Weitem an"}]'::jsonb, ''),
  ('eam-geht-da-dalles-hint-ned-zsaumm', 'Eam geht da Dalles hint ned zsaumm!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Ihm geht der Dalles hinten nicht zusammen!', '[{"kategorie": "wörtlich", "text": "\"Ihm geht vor lauter Not vorne und hinten nichts mehr zusammen!\"  2. Er steckt in großen Nöten!  3. Er ist in seiner Not völlig überfordert und kriegt nichts mehr zusammen!"}]'::jsonb, ''),
  ('dem-rennd-da-dalles-noch', 'Dem rennd da Dalles noch!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Ihm rennt der Dalles nach!', '[{"kategorie": "wörtlich", "text": "\"Er wird von bitterer Not und Armut heimgesucht!\"  2. Er ist in großen Geldnöten!  3. Er steckt tief in der Klemme – pleite bis aufs Hemd"}]'::jsonb, ''),
  ('dem-haengt-da-buri-ausse', 'Dem hängt da Buri ausse!', '', '', '', 'Wiener Gaunersprache', 'Dem hängt der Puri raus!', '[{"kategorie": "wörtlich", "text": "\"Dem hängt der Penis beim Hosenschlitz raus!\"  2. Ihm ist seine Not schon von Weitem anzusehen!  3. Dem merkt man die Pleite schon von Weitem an"}]'::jsonb, ''),
  ('host-an-dalles', 'Host an Dalles?', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'Hast du einen Dalles?', '[{"kategorie": "wörtlich", "text": "\"Hast du Not?\"  2. Bist du in Schwierigkeiten?  3. Bist du in Geldnöten?  4. Hast du finanzielle Sorgen?"}]'::jsonb, ''),
  ('i-bin-ned-wiakli-eigschbrengd-auf-a-hockn', 'I bin ned wiakli eigschbrengd auf a Hockn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich bin nicht wirklich eingesprengt auf eine Hacken!', '[{"kategorie": "wörtlich", "text": "\"Ich bin nicht wirklich versessen auf eine Arbeit!\"  2. Ich hab nicht wirklich Lust, was zu arbeiten!  3. Ich bin nicht besonders scharf auf einen Job!"}]'::jsonb, ''),
  ('i-kaunn-goa-ned-soong-wia-eigschbrengd-i-in-des-mentsch-bin', 'I kaunn goa ned soong, wia eigschbrengd I in des Mentsch bin!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Ich kann gar nicht sagen, wie eingesprengt ich in dieses Mädchen bin!', '[{"kategorie": "wörtlich", "text": "\"Ich kann gar nicht beschreiben, wie vernarrt ich in dieses Mädchen bin!\"  2. Ich kann gar nicht sagen, wie verrückt ich nach dem Mädel bin!  3. Ich kann''s kaum in Worte fassen, wie scharf ich auf dieses Mädchen bin!"}]'::jsonb, ''),
  ('si-de-augn-auskegln', 'si de Augn auskegln', '', '', '', '', 'sich die Augen auskegeln', '[{"kategorie": "", "text": "neugierig starren"}, {"kategorie": "", "text": "begierig blicken"}, {"kategorie": "", "text": "besonders fokussiert auf etwas schauen"}]'::jsonb, ''),
  ('nix-auslossn', 'nix auslossn', '', '', '', '', 'nichts auslassen', '[{"kategorie": "", "text": "knauserig sein, einen Igel in der Tasche haben"}, {"kategorie": "", "text": "keine Gelegenheit verpassen"}]'::jsonb, ''),
  ('laa-des-ins-kloo', 'Laa des ins Kloo!', '', '', '', '', 'Leere das ins Klo!', '[{"kategorie": "", "text": "Schütte das ins Klosett!  2. Leere das ins WC!"}]'::jsonb, ''),
  ('si-s-maeu-auslaarn', 'si s''Mäu auslaarn', '', '', '', '', 'sich das Maul ausleeren', '[{"kategorie": "wörtlich", "text": "\"sich den Mund leer machen\""}, {"kategorie": "fig.", "text": "\"das Herz auf der Zunge tragen\", fluchen, schelten schimpfen"}, {"kategorie": "", "text": "seinen Ärger rauslassen, sich Luft machen, die Schimpfwörter fliegen lassen, [[sich]] das Maul zerreißen, [[sich]] das Maul wetzen"}]'::jsonb, ''),
  ('si-wem-ausleichn', 'si wem ausleichn', '', '', '', '', 'sich jemanden ausleihen', '[{"kategorie": "", "text": "sich jemanden vorknöpfen, zur Brust nehmen  2. jemanden Ins Gebet nehmen, zur Rede stellen, [[wem]] ind Kost neema"}]'::jsonb, ''),
  ('ea-hod-olle-pflaunzn-saumt-da-wuazl-aussagfetzt', 'Ea hod olle Pflaunzn saumt da Wuazl aussagfetzt!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Er hat alle Pflanzen samt der Wurzel herausgefetzt!', '[{"kategorie": "wörtlich", "text": "\"Er hat alle Pflanzen samt der Wurzel herausgerissen!\"  2. Er hat die Pflanzen samt Wurzel radikal aus dem Boden rausgerupft!  3. Er hat alles Grüne samt Wurzelballen brutal aus der Erde gepflückt!"}]'::jsonb, ''),
  ('wuevueue-host-eam-aussafetzn-kenna', 'Wüvüü host eam aussafetzn kenna?', '', '', '', 'Wiener Gaunersprache', 'Wie viel hast du ihm rausfetzen können?', '[{"kategorie": "wörtlich", "text": "\"Wie viel konntest du bei ihm herausholen?\"  2. Wie viel konntest du ihm herauspressen?  3. Wie viel Geld konnest du ihm herauslocken?"}]'::jsonb, ''),
  ('waunn-i-dera-ia-schdimm-hea-fetzts-ma-de-uawaschln-aussa', 'Waunn I dera ia Schdimm hea, fetzts ma de Uawaschln aussa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn ich ihre Stimme höre, fetzt es mir die Ohrwascheln raus!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich ihre Stimme höre, fetzt es mir die Ohren raus!\"  2. Bei ihrer Stimme reißt es mir das Trommelfell raus!  3. Wenn ich ihre schneidende Stimme höre, pfeift mir das Hirn aus den Ohren!"}]'::jsonb, ''),
  ('fetz-dei-gaunzes-goeoed-ned-so-aussi', 'Fetz dei gaunzes Gööd ned so aussi!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fetz dein ganzes Geld nicht so raus!', '[{"kategorie": "wörtlich", "text": "\"Verschleuder doch nicht dein ganzes Geld!\"  2. Schmeiß doch nicht schon wieder dein ganzes Geld beim Fenster raus!  3. Verpulver dein ganzes Geld doch nicht gleich wieder!"}]'::jsonb, ''),
  ('fetz-ollas-aussi-wosd-nimma-brauchsd', 'Fetz ollas aussi, wosd nimma brauchsd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Fetz alles raus, was du nicht mehr brauchst!', '[{"kategorie": "wörtlich", "text": "\"Schmeiß alles weg, was du nicht mehr brauchst!\"  2. Miste alles aus, was nur sinnlos herumliegt!  3. Mach tabula rasa und wirf alles raus, was du nicht mehr brauchst!"}]'::jsonb, ''),
  ('fetz-dei-gaunzes-goeoed-ned-so-ausse', 'Fetz dei gaunzes Gööd ned so ausse!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Fetz dein ganzes Geld nicht so raus!', '[{"kategorie": "wörtlich", "text": "\"Verschleuder doch nicht dein ganzes Geld!\"  2. Schmeiß doch nicht schon wieder dein ganzes Geld beim Fenster raus!  3. Verpulver dein ganzes Geld doch nicht gleich wieder!"}]'::jsonb, ''),
  ('fetz-ollas-ausse-wosd-nimma-brauchsd', 'Fetz ollas ausse, wosd nimma brauchsd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Fetz alles raus, was du nicht mehr brauchst!', '[{"kategorie": "wörtlich", "text": "\"Schmeiß alles weg, was du nicht mehr brauchst!\"  2. Miste alles aus, was nur sinnlos herumliegt!  3. Mach tabula rasa und wirf alles raus, was du nicht mehr brauchst!"}]'::jsonb, ''),
  ('si-hod-sogoa-no-in-geizigstn-investoa-a-goeoed-aussareissn-kenna', 'Si hod sogoa no in geizigstn Investoa a Gööd aussareissn kenna!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie konnte sogar noch dem geizigsten Investor ein Geld herausreißen!', '[{"kategorie": "wörtlich", "text": "\"Selbst dem geizigsten Investor hat sie noch ein paar Scheine herauspressen können!\"  2. Selbst dem knausrigsten Geldgeber konnte sie am Schluss noch ein paar finanzielle Mittel für das Investment abringen!  3. Sie hat selbst dem ärgsten Geizhals am Ende noch ein paar Tausender für ihre Investition rauspressen können!"}]'::jsonb, ''),
  ('do-hoda-eam-wiida-moi-in-da-letztn-sekundn-aussegrissn', 'Do hoda eam wiida moi in da letztn Sekundn aussegrissn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da hat er ihn wieder mal in der letzten Sekunde rausgerissen!', '[{"kategorie": "wörtlich", "text": "\"Da hat er ihm wieder mal in letzter Sekunde den Arsch gerettet!\"  2. Da hat er ihm wieder mal in allerletzter Sekunde den Hintern aus dem Feuer geholt!  3. Da hat er ihn wieder mal in allerletzter Sekunde rausgehauen!"}]'::jsonb, ''),
  ('des-fensta-is-so-augrennd-dass-i-ned-ausseseeng-kau', 'Des Fensta is so augrennd, dass I ned ausseseeng kau!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Das Fenster ist so angelaufen, dass ich nicht raussehen kann!', '[{"kategorie": "wörtlich", "text": "\"Das Fenster ist so beschlagen, dass ich nicht raussehen kann!\"  2. Die Scheibe ist so beschlagen, ich sehe draußen gar nichts!  3. Die Fensterscheibe ist komplett agelaufen, ich seh kaum nach draußen!"}]'::jsonb, ''),
  ('so-an-wia-eam-kaunnst-aus-unsara-chavrusse-ned-so-afoch-aussescheibm', 'So an wia eam kaunnst aus unsara Chavrusse ned so afoch aussescheibm!', '', '', '', 'Jiddische Sprachperlen im Wienerischen', 'So einen wie ihn kannst du aus unserer Chavrusse nicht so einfach rausschieben!', '[{"kategorie": "wörtlich", "text": "\"So einen wie ihn kannst du aus unserer Clique nicht so einfach entfernen!\"  2. Den kriegst du nicht so einfach aus unserer Clique raus!  3. So jemanden wie ihn kann man nicht einfach aus der Gruppe ausschließen!"}]'::jsonb, ''),
  ('dea-scheibt-a-woeoed-moeoedung-noch-da-aundan-ausse', 'Dea scheibt a wööd Möödung noch da aundan ausse!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der schiebt eine Weltklassemeldung nach der anderen raus!', '[{"kategorie": "wörtlich", "text": "\"Der haut eine Hammermeldung nach der anderen raus!\"  2. Der feuert ein Highlight nach dem nächsten ab!  3. Der liefert eine Hammerpointe nach der nächsten ab!"}]'::jsonb, ''),
  ('de-scheisse-von-ana-gaass-schdinkt-aum-fiachtalichstn', 'De Scheisse von ana Gaass schdinkt aum fiachtalichstn!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Die Scheiße von einer Geiß stinkt am fürchterlichsten!', '[{"kategorie": "wörtlich", "text": "\"Ziegenscheiße stinkt am fürchterlichsten!\"  2. Ziegenkacke stinkt wie die Hölle!  3. Nichts stinkt so abartig wie Ziegenmist!"}]'::jsonb, ''),
  ('scheisse-jetzt-hob-i-mi-gschnittn', 'Scheisse, jetzt hob I mi gschnittn!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Scheiße, jetzt hab ich mich geschnitten!', '[{"kategorie": "wörtlich, Ausruf der Verärgerung", "text": "\"Verdammt, jetzt hab ich mich geschnitten!\"  2. \"Mist, jetzt hab ich mich in den Finger geschnitten!\"   3. Verflucht, jetzt hab ich mir die Haut aufgeschlitzt!"}]'::jsonb, ''),
  ('wia-laung-wueuesd-de-gaunze-scheisse-no-aussizaan', 'Wia laung wüüsd de gaunze Scheisse no aussizaan?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie lange willst du die ganze Scheiße noch rausziehen?', '[{"kategorie": "wörtlich", "text": "\"Wie lange willst du den Mist noch verschleppen?\"  2. Wann ziehst du endlich den Kopf aus dem Arsch und handelst?  3. Wie lange willst du dieses Theater noch weiterlaufen lassen?"}]'::jsonb, ''),
  ('zaa-aussi-de-krochn-waunnsd-di-traust', 'Zaa aussi de Krochn, waunnsd di traust!', '', '', '', 'Wiener Gaunersprache', 'Zieh raus die Krachen, wenn du dich traust!', '[{"kategorie": "wörtlich", "text": "\"Zieh deine Schusswaffe, wenn du dich traust!\"  2. Na los, zieh die Waffe – wenn du den Mut dazu hast!  3. Komm schon – greif zur Knarre, wenn du dich traust!"}]'::jsonb, ''),
  ('wia-laung-wueuesd-de-gaunze-scheisse-no-aussezaan', 'Wia laung wüüsd de gaunze Scheisse no aussezaan?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie lange willst du die ganze Scheiße noch rausziehen?', '[{"kategorie": "wörtlich", "text": "\"Wie lange willst du den Mist noch verschleppen?\"  2. Wann ziehst du endlich den Kopf aus dem Arsch und handelst?  3. Wie lange willst du dieses Theater noch weiterlaufen lassen?"}]'::jsonb, ''),
  ('zaa-ausse-de-krochn-waunnsd-di-traust', 'Zaa ausse de Krochn, waunnsd di traust!', '', '', '', 'Wiener Gaunersprache', 'Zieh raus die Krachen, wenn du dich traust!', '[{"kategorie": "wörtlich", "text": "\"Zieh deine Schusswaffe, wenn du dich traust!\"  2. Na los, zieh die Waffe – wenn du den Mut dazu hast!  3. Komm schon – greif zur Knarre, wenn du dich traust!"}]'::jsonb, ''),
  ('si-aussaschleckn', 'si aussaschleckn', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'sich aussaschlecken', '[{"kategorie": "wörtlich", "text": "\"sich rausschlecken\" (Kompositum aus dem abtrennbaren Präfix[[aussa]]=\"heraus\" und [[schlecken]]=\"lecken\")"}, {"kategorie": "Billardkugel", "text": "\"am Loch vorbeilecken\", aus dem Loch zurücklaufen, wieder aus der Tasche rollen, sich im letzten Moment aus dem Loch wieder hinausdrehen"}]'::jsonb, 'Und wiida schleckd si de schwoaze Kuugl ausn Loch aussa!'),
  ('und-wiida-schleckd-si-de-schwoaze-kuugl-ausn-loch-aussa', 'Und wiida schleckd si de schwoaze Kuugl ausn Loch aussa!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Und wieder schleckt sich die schwarze Kugel aus dem Loch raus!', '[{"kategorie": "wörtlich, Billard", "text": "\"Und wieder leckt die schwarze Kugel am Loch vorbei!\"  2. Und wieder dreht sich die schwarze Kugel im letzten Moment doch noch aus der Tasche!  3. Und wieder läuft die Schwarze aus dem Loch zurück!"}]'::jsonb, ''),
  ('si-aussischbueuen', 'si aussischbüün', '', '', '', 'Wiener Kartentipplerjargon', 'sich aussispielen', '[{"kategorie": "wörtlich", "text": "\"sich rausspielen\"  (Kompositum aus dem abtrennbaren Präfix [[aussi]]=\"hinaus\" und [[spielen]]=\"zocken\")"}, {"kategorie": "allg.", "text": "\"sich freispielen\", \"sich hinausspielen\", \"sich zum Sieg spielen\""}]'::jsonb, 'Zeaschd hob I glaubd, dass I auf da Foab sitzn bleib, owa daunn hob I mi doch no aussischbüün kenna!'),
  ('zeaschd-hob-i-glaubd-dass-i-auf-da-foab-sitzn-bleib-owa-daunn-hob-i-mi-doch-no-aussischbueuen-kenna', 'Zeaschd hob I glaubd, dass I auf da Foab sitzn bleib, owa daunn hob I mi doch no aussischbüün kenna!', '', '', '', 'Wiener Kartentipplerjargon', 'Zuerst hab ich geglaubt, dass ich auf der Farbe sitzenbleibe, aber dann hab ich mich doch noch rausspielen können!', '[{"kategorie": "wörtlich", "text": "\"Zuerst dachte ich, dass ich auf den Farbkarten sitzenbleibe, aber dann hab ich mich doch noch rausspielen können!\"  2. Anfangs sah es so aus, als würde ich die Farbkarten nicht loswerden – aber am Ende konnte ich mich doch noch freispielen!  3. Ich dachte schon, ich geh mit den Farbkarten unter – aber dann hab ich mich doch noch zum Sieg gespielt!"}]'::jsonb, 'si aussischbüün'),
  ('si-ausseschbueuen', 'si ausseschbüün', '', '', '', 'Wiener Kartentipplerjargon', 'sich aussespielen', '[{"kategorie": "wörtlich", "text": "\"sich rausspielen\"  (Kompositum aus dem abtrennbaren Präfix [[ausse]]=\"aushin\" und [[spielen]]=\"zocken\")"}, {"kategorie": "allg.", "text": "\"sich freispielen\", \"sich hinausspielen\", \"sich zum Sieg spielen\""}]'::jsonb, 'Zeaschd hob I glaubd, dass I auf da Foab sitzn bleib, owa daunn hob I mi doch no ausseschbüün kenna!'),
  ('zeaschd-hob-i-glaubd-dass-i-auf-da-foab-sitzn-bleib-owa-daunn-hob-i-mi-doch-no-ausseschbueuen-kenna', 'Zeaschd hob I glaubd, dass I auf da Foab sitzn bleib, owa daunn hob I mi doch no ausseschbüün kenna!', '', '', '', 'Wiener Kartentipplerjargon', 'Zuerst hab ich geglaubt, dass ich auf der Farbe sitzenbleibe, aber dann hab ich mich doch noch rausspielen können!', '[{"kategorie": "wörtlich", "text": "\"Zuerst dachte ich, dass ich auf den Farbkarten sitzenbleibe, aber dann hab ich mich doch noch rausspielen können!\"  2. Anfangs sah es so aus, als würde ich die Farbkarten nicht loswerden – aber am Ende konnte ich mich doch noch freispielen!  3. Ich dachte schon, ich geh mit den Farbkarten unter – aber dann hab ich mich doch noch zum Sieg gespielt!"}]'::jsonb, 'si ausseschbüün'),
  ('si-aussaseeng', 'si aussaseeng', '', '', '', 'Grundwortschatz Wienerisch', 'sich aussesehen', '[{"kategorie": "wörtlich", "text": "\"sich heraussehen\" (Kompositum aus dem abtrennbaren Präfix [[aussa]]=\"heraus\" und [[sehen]]=\"erkennen\")"}, {"kategorie": "allg.", "text": "sich auskennen, im Bilde sein, sich zurechtfinden"}]'::jsonb, 'I siich mi aussa!'),
  ('i-siich-mi-aussa', 'I siich mi aussa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich sehe mich raus!', '[{"kategorie": "wörtlich", "text": "\"Ich kenne mich aus!\"  2. Ich bin im Bilde!  3. Ich finde mich zurecht!"}]'::jsonb, ''),
  ('i-siich-mi-iwahaupt-nimma-aussa', 'I siich mi iwahaupt nimma aussa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Ich sehe mich überhaupt nicht mehr raus!', '[{"kategorie": "wörtlich", "text": "\"Ich kenne mich überhaupt nicht mehr aus!\"  2. Ich bin hoffnungslos überfordert!  3. Ich bin überhaupt nicht im Bilde!  4. Ich finde mich überhaupt nicht zurecht!"}]'::jsonb, ''),
  ('bevua-i-wo-eidiiwaen-gee-sassa-i-easchd-de-gaunze-geegnd-aus', 'Bevua I wo eidiiwän gee, sassa I easchd de gaunze Geegnd aus!', '', '', '', 'Wiener Gaunersprache', 'Bevor ich irgendwo einbrechen gehe, sasser'' ich erst die ganze Gegend aus!', '[{"kategorie": "wörtlich", "text": "\"Bevor ich irgendwo einbreche, kundschafte ich erst die ganze Gegend aus!\"  2. Bevor ich zur Tat schreite, wird erstmal die Umgebung ausspioniert!  3. Bevor ich einen Einbruch mache, checke ich erst noch gründlich die Umgebung ab!"}]'::jsonb, ''),
  ('bevua-ma-zua-toot-schreitn-ghead-zeaschd-no-ollas-gaunz-genau-ausgsassad', 'Bevua ma zua Toot schreitn, ghead zeaschd no ollas gaunz genau ausgsassad!', '', '', '', 'Wiener Gaunersprache', 'Bevor wir zur Tat schreiten, gehört zuerst noch alles ganz genau ausgesassert!', '[{"kategorie": "wörtlich", "text": "\"Bevor wir zur Tat schreiten, gehört zuerst noch alles ganz genau ausverhandelt!\"  2. Bevor wir loslegen, muss alles ganz genau abgesprochen sein!  3. Erst wenn alles restlos geklärt ist, geht’s ans Eingemachte!"}]'::jsonb, ''),
  ('de-zwaa-haum-a-kralowaad-ausgsassad', 'De zwaa haum a Kralowaad ausgsassad!', '', '', '', 'Wiener Gaunersprache', 'Die zwei habenen eine Kralowad ausgesassert!', '[{"kategorie": "wörtlich, Gaunersprache", "text": "\"Die Beiden haben einen Diebstahl ausgeheckt!\"  2. Die beiden haben einen Klau geplant!  3. Die beiden haben einen Coup ausgetüftelt!"}]'::jsonb, ''),
  ('aus-dera-hoosn-bin-i-scho-laengst-aussagwochsn', 'Aus dera Hoosn bin I scho längst aussagwochsn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Aus dieser Hose bin ich schon längst rausgewachsen!', '[{"kategorie": "wörtlich", "text": "\"Dieser Hose bin ich schon längst entwachsen!\"  2. Diese Hose passt mir schon ewig nicht mehr!  3. In diese Hose passe ich längst nicht mehr rein!"}]'::jsonb, ''),
  ('des-wochsd-ma-beim-hois-aussa', 'Des wochsd ma beim Hois aussa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das wächst mir beim Hals raus!', '[{"kategorie": "wörtlich", "text": "\"Das hängt mir langsam beim Hals raus!\"  2. Mir platzt gleich der Kragen!\"  3. Ich kann das nicht mehr hören!  4. Ich bin es leid!  5. Ich habe die Schnauze voll davon!"}]'::jsonb, ''),
  ('des-hengd-ma-beim-hois-aussa', 'Des hengd ma beim Hois aussa!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das hängt mit beim Hals heraus!', '[{"kategorie": "wörtlich", "text": "\"Das wächst mir langsam beim Hals raus!\"  2. Mir platzt gleich der Kragen!  3. Ich kann das nicht mehr hören!  4. Ich bin es leid!  5. Ich habe die Schnauze voll! ([[aussahängan]])"}]'::jsonb, ''),
  ('si-aussawuaschdln', 'si aussawuaschdln', '', '', '', 'Grundwortschatz Wienerisch', 'sich rauswursteln', '[{"kategorie": "wörtlich", "text": "\"sich herauswinden\" (Kompositum aus dem abtrennbaren Präfix [[aussa]]=\"heraus\" und [[wursteln]]=\"winden\")"}, {"kategorie": "allg.", "text": "sich aus einer Sache rauswursteln,  herausmogeln, herauslavieren, sich aus der Affäre ziehen, den Kopf aus der Schlinge ziehen"}]'::jsonb, 'Ea hod nui Plan ghobd - owa iagendwia hoda si doch o aussagwuaschdl!'),
  ('ea-hod-nui-plan-ghobd-owa-iagendwia-hoda-si-doch-o-aussagwuaschdl', 'Ea hod nui Plan ghobd - owa iagendwia hoda si doch o aussagwuaschdl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat null Plan gehabt - aber irgendwie hat er sich doch noch rausgewurschtelt!', '[{"kategorie": "wörtlich", "text": "\"Er hatte null Plan - aber irgendwie hat er sich da doch noch rausgewurstelt!\"  2. Er hatte keinen blassen Schimmer – aber am Ende hat er sich da doch noch irgendwie rausgewunden!  3. Der hatte keinen Plan, aber irgendwie hat er sich da doch noch herauslaviert!"}]'::jsonb, ''),
  ('si-aussalawian', 'si aussalawian', '', '', '', 'Grundwortschatz Wienerisch', 'sich rauslavieren', '[{"kategorie": "wörtlich", "text": "\"sich herauswinden\" (Kompositum aus dem abtrennbaren Präfix [[aussa]]=\"heraus\" und [[lavieren]]=\"winden\")"}, {"kategorie": "allg.", "text": "sich aus einer Sache rauswursteln,  herausmogeln, herauswinden, sich aus der Affäre ziehen, den Kopf aus der Schlinge ziehen"}]'::jsonb, ''),
  ('ea-hod-nui-plan-ghobd-owa-iagendwia-hoda-si-doch-o-aussalaviad', 'Ea hod nui Plan ghobd - owa iagendwia hoda si doch o aussalaviad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat null Plan gehabt - aber irgendwie hat er sich doch noch herauslaviert!', '[{"kategorie": "wörtlich", "text": "\"Er hatte null Plan - aber irgendwie hat er sich da doch noch rauslaviert!\"  2. Er hatte keinen blassen Schimmer – aber am Ende hat er sich da doch noch irgendwie rausgewunden!  3. Der hatte keinen Plan, aber irgendwie hat er sich da doch noch rausgewurstelt!"}]'::jsonb, ''),
  ('wem-wos-aussazuuzln', 'wem wos aussazuuzln', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem etwas rauszuzeln', '[{"kategorie": "wörtlich", "text": "\"jemandem etwas rauslutschen\""}, {"kategorie": "fig.", "text": "jemandem eine Information entlocken"}, {"kategorie": "", "text": "jemandem etwas herauspressen"}]'::jsonb, ''),
  ('loss-da-ned-ollas-aussazuuzln', 'Loss da ned ollas aussazuuzln!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Lass dir nicht alles rauszuzeln!', '[{"kategorie": "wörtlich", "text": "\"Lass dir nicht alles rauslutschen!\"  2. (fig.) \"Komm schon, lass dir nicht alles aus der Nase ziehen!\"  3. Lass dir nicht jedes Wort mit der Pinzette rausholen!  4. Lass dir nicht die Würmer aus der Nase ziehen!"}]'::jsonb, ''),
  ('si-aussaschoeoen', 'si aussaschöön', '', '', '', 'Grundwortschatz Wienerisch', 'sich aussaschälen', '[{"kategorie": "wörtlich", "text": "\"sich herausschälen\" (Kompositum aus dem abtrennbaren Präfix [[aussa]]=\"heraus\" und [[schälen]]=\"die Haut abziehen\")"}, {"kategorie": "allg.", "text": "sich aus dem Gewand herausschälen, sich aus dem Gewand lösen, sich aus dem Stoff winden, sich ausziehen, sich entblättern"}]'::jsonb, 'Dea schööd si aussa aus seina Aansapania, ois häd eam wea einebeegld!'),
  ('dea-schoeoed-si-aussa-aus-seina-aansapania-ois-haed-eam-wea-einebeegld', 'Dea schööd si aussa aus seina Aansapania, ois häd eam wea einebeegld!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der schält sich raus aus seiner Einserpanier, als hätte ihn jemand da reingebügelt!', '[{"kategorie": "wörtlich", "text": "\"Der schält sich raus aus seinem Sonntagsgewand, als hätte ihn jemand da reingebügelt!\"  2. Der kämpft sich aus seinem Sonntagsanzug raus wie aus ’nem zu engen Ganzkörperkondom!  3. Der schält sich aus seinem Sonntagsgewand raus wie eine alte Bratwurst aus der Haut!"}]'::jsonb, 'si aussaschöön'),
  ('schmiia-in-zeena-oo-dea-deaf-heid-kaan-schdich-mochn', 'Schmiia in Zeena oo - dea deaf heid kaan Schdich mochn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Schmier den Zehner ab - der darf heute keinen Stich machen!', '[{"kategorie": "wörtlich, Fußballerjargon", "text": "\"Nimm den Zehner durch Manndeckung aus dem Spiel - der darf heute keinen Stich machen!\"  2. Den Spielmacher musst du manndecken und komplett neutralisieren - der darf keinen Raum bekommen!  3. Du musst den Spielmacher manndecken - der darf heute keinen Zugriff aufs Spiel bekommen!"}]'::jsonb, ''),
  ('dea-hod-imma-no-ned-oogschmiiad-dass-sei-oide-fremdpuudad', 'Dea hod imma no ned oogschmiiad, dass sei Oide fremdpuudad!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der hat immer noch nicht abgeschmiert, dass seine Alte fremdpudert!', '[{"kategorie": "wörtlich", "text": "\"Der hat immer noch nicht mitgekriegt, dass seine Alte fremdgeht!\"  2. Der checkt immer noch nicht, dass ihm seine Alte Hörner aufsetzt!  3. Der Typ hat noch immer nicht geschnallt, dass ihn seine Alte betrügt!"}]'::jsonb, ''),
  ('du-bleibsd-draussn-und-schmiiasd-oo-wia-san-in-5-minuutn-wieda-zruck', 'Du bleibsd draussn und schmiiasd oo - wia san in 5 Minuutn wieda zruck!', '', '', '', 'Wiener Gaunersprache', 'Du bleibst draußen und schmierst ab – wir sind in fünf Minuten wieder zurück!', '[{"kategorie": "wörtlich", "text": "\"Du bleibst draußen und stehst Schmiere – wir sind in fünf Minuten wieder zurück!\"  2. Du bleibst draußen und hältst die Augen offen – in fünf Minuten sind wir wieder raus!  3. Stell dich an die Ecke und schmier ab – wir sind gleich zurück!"}]'::jsonb, ''),
  ('waunn-da-muarl-ooschmiiad-bisd-gliifad', 'Waunn da Muarl ooschmiiad, bisd gliifad!', '', '', '', 'Wiener Mechaniker-Slang', 'Wenn der Murl abschmiert, bist du geliefert!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Motor plötzlich ausfällt, bist du aufgeschmissen!\"  2. Wenn der Motor verreckt, war’s das für dich!  3. Wenn der Motor den Geist aufgibt, bist du erledigt!"}]'::jsonb, ''),
  ('waunnsd-z-laungsaum-wiasd-im-schdeigfluug-kaunn-da-da-voogl-gaunz-schnoeoe-ooschmiian', 'Waunnsd z''laungsaum wiasd im Schdeigfluug, kaunn da da Voogl gaunz schnöö ooschmiian!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wenn du zu langsam wirst im Steigflug, kann dir der Vogel ganz schnell abschmieren!', '[{"kategorie": "wörtlich", "text": "\"Verlierst du im Steigflug an Geschwindigkeit, kann dir der Flieger ganz schnell absacken!\"  2. Langsam steigen heißt schnell fallen – Thermik kennt da keinen Spaß!  3. Wird die Geschwindigkeit im Steigflug zu gering, besteht die Gefahr eines Strömungsabrisses!"}]'::jsonb, ''),
  ('tiimoaweid-haassd-bei-uns-aana-schreibd-und-fuenfe-schmiian-oo', 'Tiimoaweid haassd bei uns: Aana schreibd und fünfe schmiian oo!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Teamarbeit heißt bei uns: Einer schreibt und fünf schmieren ab!', '[{"kategorie": "wörtlich", "text": "\"Bei uns bedeutet Gruppenarbeit: Einer rackert, der Rest schreibt’s ab!\"  2. Gruppenprojekt heißt bei uns: Einer schreibt, alle anderen setzen ihren Namen darunter!  3. Gelebte Gruppenarbeit: Einer schreibt, fünf schmieren ab!"}]'::jsonb, ''),
  ('jeeds-moi-wiida-schmiiada-mid-seina-ex-oo', 'Jeeds Moi wiida schmiiada mid seina Ex oo!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Jedes Mal wieder schmiert er mit seiner Ex ab!', '[{"kategorie": "wörtlich", "text": "\"Immer wieder aufs Neue wird er mit seiner Ex intim!\" =  2. Zwischen ihm und seiner Ex kommt es nach wie vor regelmäßig zu Intimitäten!  3. Er und seine Ex landen landen immer wieder miteinander im Bett!"}]'::jsonb, ''),
  ('de-krimineesa-haum-in-schdiazla-drei-wochn-laung-oogschmiiad', 'De Krimineesa haum in Schdiazla drei Wochn laung oogschmiiad!', '', '', '', 'Wiener Gaunersprache', 'Die Krimineser haben den Stürzler drei Wochen lang abgeschmiert!', '[{"kategorie": "wörtlich", "text": "\"Die Kriminalbeamten haben den Gangster drei Wochen lang observiert!\"  2. Die Ermittler haben den Tatverdächtigen drei Wochen lang überwacht!  3. Der Rumtreiber stand drei Wochen lang unter Beobachtung der Kriminalpolizei!"}]'::jsonb, ''),
  ('a-schdiazla-tuad-in-gaunzn-toog-nix-aundas-ois-drauf-woatn-dass-eams-leebm-iagendwaunn-oohoid', 'A Schdiazla tuad in gaunzn Toog nix aundas ois drauf woatn, dass eams Leebm iagendwaunn oohoid!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ein Stürzler tut den ganzen Tag nichts anderes als darauf zu warten, dass ihn das Leben irgendwann abholt!', '[{"kategorie": "wörtlich", "text": "\"Ein Tagedieb tut den ganzen Tag nichts anderes als darauf zu warten, dass ihn das Leben irgendwann abholt!\"  2. Ein Müßiggänger hängt einfach ab – in der Hoffnung, dass das Leben schon irgendwas mit ihm vorhat!  3. Als Herumtreiber ohne Ziel wartet er den ganzen Tag darauf, dass das Leben ihn rettet – dabei weiß er nicht mal, wovor!"}]'::jsonb, ''),
  ('si-wos-ausschnopsn', 'si wos ausschnopsn', '', '', '', 'Grundwortschatz Wienerisch', 'sich etwas ausschnapsen', '[{"kategorie": "wörtlich", "text": "\"sich etwas ausschnapsen\" (vom mittelhochdeutschen \"snappen\"=\"etwas schnell greifen\")"}, {"kategorie": "allg.", "text": "\"sich etwas im Kartenspiel, durch Verhandlung oder Absprache sichern\", \"sich etwas auswürfeln\", \"sich etwas ausmachen\", \"sich einigen\", etwas ausverhandeln, vereinbaren, regeln"}]'::jsonb, 'Schnops da des mit eam direkt aus, bevua da Oide no Wind davoo kriagd!'),
  ('schnops-da-des-mit-eam-direkt-aus-bevua-da-oide-no-wind-davoo-kriagd', 'Schnops da des mit eam direkt aus, bevua da Oide no Wind davoo kriagd!', '', '', '', 'Wiener Gaunersprache', 'Schnaps dir das mit ihm direkt aus, bevor der Alte noch Wind davon kriegt!', '[{"kategorie": "wörtlich", "text": "\"Regel das direkt mit ihm, bevor der Chef noch etwas davon mitbekommt!\"  2. Verhandel das im Stillen mit ihm aus, bevor der Chef noch etwas spitzkriegt!  3. Einige dich mit ihm, das spart dir eine Menge mit dem Alten!"}]'::jsonb, ''),
  ('de-kotz-hod-scho-wiida-ausgschid', 'De Kotz hod scho wiida ausgschid!', '', '', '', '', 'Die Katze hat schon wieder ausgeschüttet!', '[{"kategorie": "", "text": "Die Katze hat schon wieder Junge bekommen!  2. Die Katze hat schon wieder kleine Fellbomben geworfen!  3. Die Katze hat schon wieder Nachwuchs zur Welt gebracht!"}]'::jsonb, ''),
  ('wem-s-kraut-ausschiidn', 'wem ''s Kraut ausschììdn', '', '', '', '', 'jemandem das Kraut ausschütten', '[{"kategorie": "wörtlich", "text": "sich mit jemandem gründlich verkrachen"}, {"kategorie": "", "text": "sich bei jemandem endgültig unbeliebt machen"}, {"kategorie": "", "text": "es sich mit jemandem auf ewig verscherzen"}]'::jsonb, ''),
  ('si-ausschiidn-vua-lochn', 'si ausschiidn vua Lochn', '', '', '', '', 'sich ausschütten vor Lachen', '[{"kategorie": "", "text": "sich kaputtlachen, sich totlachen"}, {"kategorie": "", "text": "besonders laut und ausgiebig lachen"}]'::jsonb, ''),
  ('da-eifaadla-duach-de-schnittschdoeoen-hod-de-gaunze-obwea-ausgheewaed', 'Da Eifaadla duach de Schnittschdöön hod de gaunze Obwea ausgheewäd!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Einfädler durch die Schnittstelle hat die ganze Abwehrt ausgehebelt!', '[{"kategorie": "wörtlich", "text": "\"Der öffnende Pass durch die Schnittstelle hat die gesamte Abwehr komplett ausgehebelt!\"  2. Der präzise Steckpass hat die gesamte Defensive ausa dem Spiel genommen!  3. Der geniale Pass durch die Schnittstelle hat die gegnerische Abwehr im Alleingang zerlegt!"}]'::jsonb, ''),
  ('des-is-da-eifaadla-min-toedlichn-pass-dea-waass-wo-s-richtig-wee-tuad', 'Des is da Eifaadla min tödlichn Pass - dea waass, wo''s richtig wee tuad!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Das ist der Einfädler mit dem tödlichen Pass - der weiß, wo''s richtig weh tut!', '[{"kategorie": "wörtlich", "text": "\"Das ist der Vorlagengeber mit dem tödlichen Pass - der weiß, wo''s richtig weh tut!\"  2. Das ist der Mann für den tödlichen Pass – der findet immer genau die Lücke in der Abwehr!  3. Er ist der Assistkönig, der weiß, wann und wo’s dem Gegner wehtut!"}]'::jsonb, ''),
  ('de-haum-so-oag-eineghockd-dass-ma-jetzt-lauta-valetzte-haum', 'De haum so oag eineghockd, dass ma jetzt lauta Valetzte haum!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die haben so arg reingehackt, dass wir jetzt lauter Verletzte haben!', '[{"kategorie": "wörtlich", "text": "\"Die sind so heftig reingeholzt, dass wir jetzt lauter Verletzte haben!\"  2. Die haben so brutal gespielt, dass bei uns jetzt die halbe Mannschaft verletzt ist!  3. Die haben so brutal reingetreten, dass jetzt die halbe Truppe bei uns verletzt ist!"}]'::jsonb, ''),
  ('bei-de-blaun-is-jeda-zweite-a-eighockda', 'Bei de Blaun is jeda Zweite a Eighockda!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Bei den Blauen ist jeder Zweite ein Eingehackter!', '[{"kategorie": "wörtlich", "text": "\"Bei der Freiheitlichen Partei ist jeder Zweite ein Eingeritzter!\"  2. \"Bei der Freiheitlichen Partei ist jeder Zweite Mitglied einer schlagenden Verbindung!\" (Mitglied einer studentischen Verbindung, in der das Fechten mit scharfen Waffen, Körper- und Gesichtstreffern [\"Mensur-Fechten\"] ein zentraler Bestandteil der Tradition ist)"}, {"kategorie": "", "text": "Bei der FPÖ trägt jeder Zweite Spuren vom Mensur-Fechten im Gesicht!"}]'::jsonb, ''),
  ('i-loss-mi-ausn-tiim-sicha-ned-aussibeissn', 'I loss mi ausn Tiim sicha ned aussibeissn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Ich lasse mich aus dem Team sicher nicht rausbeißen!', '[{"kategorie": "wörtlich", "text": "\"Ich lasse mich aus meiner Mannschaft ganz bestimmt nicht hinausdrängen!\"  2. Ich lasse mich aus dem Team sicher nicht rauskicken!  3. Wer mich aus dem Team drängen will, muss sich warm anziehen! (sierhe auch [[aussibeissn]])"}]'::jsonb, ''),
  ('waunnsd-ned-aufpassd-draans-di-ausn-tiim-aussi', 'Waunnsd ned aufpassd, draans di ausn Tiim aussi!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Wenn du nicht aufpasst, drehen sie dich aus dem Team raus!', '[{"kategorie": "wörtlich", "text": "\"Wenn du nicht aufpasst, werden sie dich aus der Mannschaft rausdrängen!\"  2. Du musst aufpassen – sonst verlierst du deinen Platz im Team!  3. Gib Acht, sonst setzen die dich schneller aufs Abstellgleis, als du denkst!"}]'::jsonb, ''),
  ('dea-is-a-joa-vaheirat-tuad-owa-no-imma-aussigroosn', 'Dea is a Joa vaheirat, tuad owa no imma aussigroosn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der ist ein Jahr verheiratet, tut aber noch immer rausgrasen!', '[{"kategorie": "wörtlich", "text": "\"Der ist seit einem Jahr verheiratet, geht aber nach wie vor fremd!\"  2. Der ist zwar seit einem Jahr verheiratet, geht aber immer noch fremd wie eh und je!  3. Er hat schon immer außerhalb der eigenen Weide gegrast - jetzt auch mit Ehering am Finger!"}]'::jsonb, ''),
  ('tua-ned-aussigroosn-bleib-in-deina-gossn', 'Tua ned aussigroosn - bleib in deina Gossn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Tu nicht rausgrasen - bleib in deiner Gasse!', '[{"kategorie": "wörtlich", "text": "\"Tu nicht rausgrasen - bleib in deinem angestammten Bereich!\"  2. Überschreite nicht deinen Zuständigkeitsrahmen -  bleib in deinem angestammten Bereich!  3. Weide nicht auf fremden Wiesen - bleib in deinem Revier!"}]'::jsonb, ''),
  ('wem-ausselaanan', 'wem ausselaanan', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden rauslehnen', '[{"kategorie": "wörtlich", "text": "\"jemanden von außen an die Mauer lehnen\" (vom mittelhochdeutschen \"lënen\"=\"anlehnen\")"}, {"kategorie": "allg., transitiv", "text": "jemanden vor die Tür setzen, aus dem Haus werfen, die Tür weisen,  des Lokals verweisen, rausschmeißen"}]'::jsonb, ''),
  ('und-waunns-uns-duat-ausselaanan-besuch-ma-dei-latifundiae-no-fiara-schbeib-aachtal', 'Und waunns uns duat ausselaanan, besuch ma dei Latifundiä no fiara Schbeib-Aachtal!', '', '', '', 'Echte Wiener Schmähperlen', 'Und wenn sie uns dort rauslehnen, besuchen wir deine Latifundie noch für ein Speibachterl!', '[{"kategorie": "wörtlich", "text": "\"Und wenn sie uns dort vor die Tür setzen, besuchen wir deine Latifundie noch für ein letztes Kotzachterl!\"  2. Und wenn sie uns dort rausschmeißen, dann kippen wir bei dir halt noch ein Abschiedsachterl!  3. Wenn sie uns dort rauswerfen, dann gibt’s bei dir daheim noch das Exitus-Achterl!"}]'::jsonb, 'wem ausselaanan'),
  ('schbeib-achtal', 'Schbeib-Achtal', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Speibachterl', '[{"kategorie": "wörtlich", "text": "\"Kotzachterl\" (Determinativkompositum aus \"speiben\"=\"kotzen\" und \"Achterl\"=\"Achtelliterglas Wein\")"}, {"kategorie": "scherzhaft für", "text": "\"letztes Achtelliterglas Wein vor dem Kotzen\", \"Abgangsachterl\", \"Abschiedsachterl\", \"Exitus-Achterl\""}]'::jsonb, ''),
  ('wem-de-bock-ausselaanan', 'wem de Bock ausselaanan', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem die Bock rauslehnen', '[{"kategorie": "wörtlich", "text": "\"jemandem die Schuhe draußen an die Tür lehnen\""}, {"kategorie": "fig.", "text": "jemanden vor die Tür setzen"}, {"kategorie": "", "text": "jemanden aus dem Haus werfen\""}]'::jsonb, ''),
  ('wem-de-bock-vuad-tia-schdoeoen', 'wem de Bock vuad Tia schdöön', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'jemandem die Bock vor die Türe stellen', '[{"kategorie": "wörtlich", "text": "\"jemandem die Schuhe vor die Türe stellen\""}, {"kategorie": "fig.", "text": "jemanden vor die Tür setzen"}, {"kategorie": "", "text": "jemanden aus dem Haus werfen\""}]'::jsonb, ''),
  ('ea-is-ausseglaand-wuan', 'Ea is ausseglaand wuan!', '', '', '', 'Wiener Gaunersprache', 'Er ist rausgelehnt worden!', '[{"kategorie": "wörtlich", "text": "\"Man hat ihn draußen an die Tür gelehnt!\"  2. Man hat ihn vor die Tür gesetzt!  3. Man hat ihn aus dem Haus geworfen!  4. Man hat sich seiner entledigt!"}]'::jsonb, ''),
  ('wem-s-goeoed-aussareissn', 'wem s''Gööd aussareissn', '', '', '', 'Wiener Gaunersprache', 'jemandem das Geld herausreißen', '[{"kategorie": "wörtlich", "text": "\"jemandem das Geld aus der Tasche ziehen\""}, {"kategorie": "", "text": "jemanden um seine Barschaft erleichtern"}, {"kategorie": "", "text": "jemanden abzocken, schröpfen, leersaugen"}]'::jsonb, 'Loss da von dem Halawachl nua ka Gööd aussareissn!'),
  ('loss-da-von-dem-halawachl-nua-ka-goeoed-aussareissn', 'Loss da von dem Halawachl nua ka Gööd aussareissn!', '', '', '', 'Wiener Gaunersprache', 'Lass dir von diesem Halawachl bloß kein Geld rausreißen!', '[{"kategorie": "wörtlich", "text": "\"Lass dir von diesem Hallodri bloß kein Geld rausreißen!\"  2. Lass dich von dem Kerl bloß nicht abzocken!  3. Pass auf, dass dir dieser Strolch nicht das Geld aus der Tasche zieht!"}]'::jsonb, 'wem s''Gööd aussareissn'),
  ('jetzt-haumma-des-gschissane-auswendig', 'Jetzt haumma des gschissane Auswendig!', '', '', '', '', 'Jetzt haben wir das geschissene Auswendig!', '[{"kategorie": "", "text": "Jetzt stecken wir gehörig in der Klemme!  2. Jetzt haben wir den [[Scherm]] auf!  3. Jetzt samma in da [[Geam]]!"}]'::jsonb, ''),
  ('schaun-wiara-autobus', 'schaun wiara Autobus', '', '', '', '', 'schauen wie ein Autobus', '[{"kategorie": "", "text": "[[schauen]] wie der Ochs vorm Berg"}, {"kategorie": "", "text": "dreinschauen wie ein begossener Pudel"}, {"kategorie": "", "text": "wie ein Mondkalb aus der Wäsche gucken"}, {"kategorie": "", "text": "[[schauen]] wie die Tante am Kirtag"}, {"kategorie": "", "text": "große Augen machen, mit offenem Mund dastehen, [[betroppezd]] dreinschauen, sprachlos sein"}]'::jsonb, ''),
  ('schaun-wiara-aufgschreckds-hendl', 'schaun wiara aufgschreckds Hendl', '', '', '', '', 'schauen wie ein aufgescchrecktes Hendl', '[{"kategorie": "wörtlich", "text": "\"schauen wie ein aufgeschrecktes Huhn\""}, {"kategorie": "", "text": "schauen wie der Ochs vorm Berg"}, {"kategorie": "", "text": "dreinschauen wie ein begossener Pudel"}, {"kategorie": "", "text": "wie ein Mondkalb aus der Wäsche gucken"}, {"kategorie": "", "text": "[[schauen]] wie die Tante am Kirtag"}, {"kategorie": "", "text": "große Augen machen, mit offenem Mund dastehen, [[betroppezd]] dreinschauen, sprachlos sein"}]'::jsonb, ''),
  ('schaun-wia-da-ochs-vuam-beag', 'schaun wia da Ochs vuam Beag', '', '', '', '', 'schauen wie der Ochse vorm Berg', '[{"kategorie": "", "text": "[[schauen]] wie ein Autobus"}, {"kategorie": "", "text": "dreinschauen wie ein begossener Pudel"}, {"kategorie": "", "text": "wie ein Mondkalb aus der Wäsche gucken"}, {"kategorie": "", "text": "[[schauen]] wie die Tante am Kirtag"}, {"kategorie": "", "text": "große Augen machen, mit offenem Mund dastehen, [[betroppezd]] dreinschauen, sprachlos sein"}]'::jsonb, ''),
  ('wem-aane-auf-de-aawiche-seitn-geem', 'wem aane auf de aawiche Seitn geem', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem eine auf die ''abige'' Seite geben', '[{"kategorie": "wörtlich", "text": "\"jemandem eine auf die abgewandte Seite verpassen\""}, {"kategorie": "", "text": "jemandem eins aufs Hinterteil schlagen"}, {"kategorie": "", "text": "jemandem einen Klaps auf den Hintern geben"}, {"kategorie": "", "text": "jemandem einen Tritt in den Hintern verpassen"}]'::jsonb, ''),
  ('waunn-da-dea-aane-auf-de-aawiche-seitn-gibd-kaunnst-drei-wochn-ned-gscheid-aum-oasch-sitzen', 'Waunn da dea aane auf de aawiche Seitn gibd, kaunnst drei Wochn ned gscheid aum Oasch sitzen!', '', '', '', 'Wiener Gaunersprache', 'Wenn dir der eine auf die ''abige'' Seite gibt, kannst du drei Wochen nicht gescheit auf deinem Arsch sitzen!', '[{"kategorie": "wörtlich", "text": "\"Wenn dir der eine auf die abgewandte Seite gibt, kannst du drei Wochen nicht gescheit auf deinem Arsch sitzen!\"  2. Wenn dir der einen Tritt in den Hintern verpasst, kannst du drei Wochen nicht mehr richtig auf deinem Arsch sitzen!  3. Wenn der dir in den Arsch tritt, brauchst du drei Wochen lang einen Sitzpolster!"}]'::jsonb, 'wem aane auf de aawiche Seitn geem'),
  ('wea-mi-auliagd-kriagd-ane-auf-sei-aawiche-seitn', 'Wea mi auliagd, kriagd ane auf sei aawiche Seitn!', '', '', '', 'Wiener Gaunersprache', 'Wer mich anlügt, der kriegt eine auf seine ''abige'' Seite!', '[{"kategorie": "wörtlich", "text": "\"Wer mich anlügt, der kreigt eine auf seine abgewandte, hintere Seite!\"  2. Wer mich anlügt, kriegt eine in den Hintern!  3. Wer mich verarscht, kriegt einen Tritt in den Hintern!"}]'::jsonb, ''),
  ('ea-hod-in-schdrumpf-auf-da-aawichn-seitn-aunzogn', 'Ea hod in Schdrumpf auf da aawichn Seitn aunzogn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat den Strumpf auf der awichen Seite angezogen!', '[{"kategorie": "wörtlich", "text": "\"Er hat den Strumpf verkehrt herum angezogen!\"  2. Er hat den Strumpf falsch rum angezogen!  3. Er trägt seinen Strumpf inside-out!\""}]'::jsonb, ''),
  ('de-aawiche-hoda-si-mea-ois-vadiint', 'De Aawiche hoda si mea ois vadiint!', '', '', '', 'Wiener Gaunersprache', 'Diese Awiche hat er sich mehr als verdient!', '[{"kategorie": "wörtlich", "text": "\"Diese Handrückenschelle hat er sich mehr als verdient!\"  2. Diese Ohrfeige mit dem Handrücken hat er sich redlich verdient!  3. Dieser \"Handrücken-Kinnlader\" war für ihn längst überfällig!"}]'::jsonb, ''),
  ('de-vakeade-hoda-si-mea-ois-vadiint', 'De Vakeade hoda si mea ois vadiint!', '', '', '', 'Wiener Gaunersprache', 'Diese Verkehrte hat er sich mehr als verdient!', '[{"kategorie": "wörtlich", "text": "\"Diese Handrückenschelle hat er sich mehr als verdient!\"  2. Diese Ohrfeige mit dem Handrücken hat er sich redlich verdient!  3. Dieser \"Handrücken-Kinnlader\" war für ihn längst überfällig!"}]'::jsonb, ''),
  ('ea-is-a-waeae-hod-de-hockn-owa-mit-vue-vitamin-b-kriagt', 'Ea is a Wää, hod de Hockn owa mit vü Vitamin B kriagt!', '', '', '', '', 'Er ist ein Weh, hat die Hacke aber mit viel Vitamin B gekriegt!', '[{"kategorie": "", "text": "Er ist ein Loser, hat den Job aber mit viel Vitamin B bekommen!  2. Er hat keine Ahnung, hat die Stelle aber über Beziehungen bekommen!"}]'::jsonb, ''),
  ('nummaria-da-deine-baana', 'Nummaria da deine Baana!', '', '', '', 'Wiener Gaunersprache', 'Nummeriere dir deine Knochen!', '[{"kategorie": "wörtlich", "text": "\"Nummeriere dir deine Knochen, bevor ich dich auseinandernehme!\"  2. Markier dir deine Gelenke – nachher weißt du sonst nimmer, wo oben und unten ist!  3. Nummeriere deine Knochen, bevor ich dich in deine Einzelteile zerlege!   2."}]'::jsonb, ''),
  ('s-narrische-baa', 's narrische Baa', '', '', '', 'Wiener Sprüche, die sitzen!', 'das närrische Bein', '[{"kategorie": "wörtlich", "text": "\"Narrenbein\" (\"der verrückte Knochen\", englisch: [GB] \"funny bone\", [US] \"crazy bone\")"}, {"kategorie": "med.", "text": "\"Ellennerv an der Innenseite des Ellbogens\" (\"Nervus ulnaris\" =  jene Stelle am Ellbogen, wo der Ellennerv oberflächlich verläuft und ein Stoß ein stechendes Kribbeln bis in den kleinen Finger auslöst, manchmal sogar \"bis ins Hirn hinauf\"), \"Musikantenknochen\", [[ das damische Aderl]]"}]'::jsonb, ''),
  ('du-brauchsda-es-narrische-baa-nua-leichd-auhaun-und-schoo-taunzd-da-s-hian', 'Du brauchsda es narrische Baa nua leichd auhaun, und schoo taunzd da s''Hian!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Du brauchst dir das narrische Bein nur leicht anzuhauen, und schon tanzt dir das Hirn!', '[{"kategorie": "wörtlich", "text": "\"Du brauchst dir das narrische Bein nur leicht anzuschlagen– und schon springt dir das Hirn fast aus’m Schädel!\"  2.  Ein leichter Stoß gegen den Musikantenknochen genügt, und schon schießt dir der Schmerz bis in die Haarspitzen!  3. Schon die kleinste Berührung am [[damischen]] Aderl fühlt sich an, als ob dir jemand ein Messer reinsticht!"}]'::jsonb, 's narrische Baa'),
  ('s-damische-aadal', 's damische Aadal', '', '', '', 'Krank & kuriert auf Wienerisch', 'das damische Aderl', '[{"kategorie": "wörtlich", "text": "\"das verrückte Äderchen\" (englisch: [GB] \"funny bone\", [US] \"crazy bone\")"}, {"kategorie": "med.", "text": "\"Ellennerv an der Innenseite des Ellbogens\" (\"Nervus ulnaris\" =  jene Stelle am Ellbogen, wo der Ellennerv oberflächlich verläuft und ein Stoß ein stechendes Kribbeln bis in den kleinen Finger auslöst, manchmal sogar \"bis ins Hirn hinauf\"), \"Musikantenknochen\", à''s narrische Baa"}]'::jsonb, ''),
  ('du-brauchsda-es-damische-aadal-nua-leichd-auhaun-und-schoo-taunzd-da-s-hian', 'Du brauchsda es damische Aadal nua leichd auhaun, und schoo taunzd da s''Hian!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Du brauchst dir das damische Äderchen nur leicht anzuhauen, und schon tanzt dir das Hirn!', '[{"kategorie": "wörtlich", "text": "\"Du brauchst dir das narrische Bein nur leicht anzuschlagen– und schon springt dir das Hirn fast aus’m Schädel!\"  2.  Ein leichter Stoß gegen den Musikantenknochen genügt, und schon schießt dir der Schmerz bis in die Haarspitzen!  3. Schon die kleinste Berührung am damischen Aderl fühlt sich an, als ob dir jemand ein Messer reinsticht!"}]'::jsonb, ''),
  ('waunn-dea-baanageist-in-da-tia-schdeed-glaubsd-es-is-hellowiin', 'Waunn dea Baanageist in da Tia schdeed, glaubsd, es is Hellowiin!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn dieser Knochengeist in der Tür steht, glaubst du, es ist Halloween!', '[{"kategorie": "wörtlich", "text": "\"Wenn dieses Knochengespenst in der Tür steht, glaubt man, es ist Halloween!\"  2. Wenn der Hungerhaken im Türrahmen steht, meint man, gleich bricht die Geisterstunde los!  3. Wenn das wandelnde Gerippe auftaucht, denkt man, ein Skelett hat Ausgang bekommen!"}]'::jsonb, ''),
  ('seit-da-diaeaet-schauts-aus-wiara-baanagschdoeoe-auf-hei-hiils', 'Seit da Diäät schauts aus wiara Baanagschdöö auf Hei Hiils!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Seit der Diät schaut sie aus wie ein Knochengestell auf High Heels!', '[{"kategorie": "wörtlich", "text": "\"Seit der Diät sieht sie aus wie ein wandelnder Kleiderbügel in Stöckelschuhen!\"  2. Seit der Diät läuft sie rum wie ein Skelett in Stilettos!  3. Seit ihrer Diät hat man das Gefühl, jemand hätte ein Gerippe in Designerschuhen losgelassen!"}]'::jsonb, ''),
  ('a-baanahaufn-mid-a-bissl-aan-peedasueue-oobmdrauf-mochd-no-laung-kaa-suundoogsbraadl', 'A Baanahaufn mid a bissl aan Peedasüü oobmdrauf mochd no laung kaa Suundoogsbraadl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ein Knochenhaufen mit ein bisschen Petersilie obendrauf macht noch lange keinen Sonntagsbraten!', '[{"kategorie": "wörtlich", "text": "\"Ein bisschen Grünzeug obendrauf macht aus einem Gerippe noch lange keinen Festtagsbraten!\"  2. Ein Skelett mit ein bisschen Kräuterdeko obendrauf ist noch lange kein Sonntagsbraten!  3. Ein ausgebeinter Rest mit Blattwerk ist keine ordentliche Mahlzeit, geschweige denn ein Sonntagsbraten!"}]'::jsonb, ''),
  ('dea-schaud-aus-wiara-klaana-baanahaufn-owar-enagii-hoda-fia-fuemfe', 'Dea schaud aus wiara klaana Baanahaufn, owar Enagii hoda fia fümfe!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der schaut aus wie ein kleiner Knochenhaufen, aber Energie hat er wie fünfe!', '[{"kategorie": "wörtlich", "text": "\"Der kommt daher wie ein kleiner Knochenhaufen, aber Energie hat er wie fünf!\"  2. Er sieht zwar aus wie ein Hungerhaken, aber er hat Power für fünf!  3. Der Kerl ist mehr Knochen als Fleisch, aber geht ab wie ein Wirbelsturm!"}]'::jsonb, ''),
  ('bei-dem-baanahengst-kaunnsd-de-rippaln-aanzln-zoeoen', 'Bei dem Baanahengst kaunnsd de Rippaln aanzln zöön!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Bei diesem Knochenhengst kannst du die Rippchen einzeln zählen!', '[{"kategorie": "wörtlich", "text": "\"Bei dem wandelnden Röntgenbild siehst du jede einzelne Rippe durchblitzen!\"  2. Dieser Hungerhaken hat so wenig Fleisch auf den Knochen, dass du jede einzelne Rippe durchnummerieren kannst!  3. Dieses Skelett brauchst du nicht röntgen - bei dem sieht man jede einzelne Rippe auch so!"}]'::jsonb, ''),
  ('waunn-dea-so-weidamochd-taunzda-boid-min-baananan-wiina-woiza', 'Waunn dea so weidamochd, taunzda boid min Baananan Wiina Woiza!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Wenn der so weitermacht, tanzt er bald mit’m Beinernen Wiener Walzer!', '[{"kategorie": "wörtlich", "text": "\"Wenn der so weitermacht, tanzt er bald mit’m Knochenmann Wiener Walzer!\"  2. So wie der Gas gibt, wird ihm der Knochenmann bald mit''m Taktstock winken!  3. Mit dem Tempo wird er sich beim Sensenmann bald eine Direktüberfahrt in die Ewigkeit buchen!"}]'::jsonb, ''),
  ('da-hoizschnitzde-geed-imma-baahoat-eine-dea-ziagd-nii-zruck', 'Da Hoizschnitzde geed imma baahoat eine - dea ziagd nii zruck!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Holzgeschnitzte geht immer beinhart rein - der zieht nie zurück!', '[{"kategorie": "wörtlich", "text": "\"Der Holzhacker geht in jeden Zweikampf beinhart rein - der zieht nie zurück!\"  2. Dieser Abwehrrecke ist beinhart - der hat Beton in den Schuhen und Stahl in den Knochen!  3. Dieser Verteidiger ist ein beinharter Abräumer, der nie zurückzieht – da wird jeder Zweikampf zur Vollkontaktzone!"}]'::jsonb, ''),
  ('dea-kiifaed-aun-de-baanln-umanaund-ois-warada-a-oachkatzl', 'Dea kiifäd aun de Baanln umanaund, ois warada a Oachkatzl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der kiefelt an den Beinchen rum, als wäre er ein Eichkatzerl!', '[{"kategorie": "wörtlich", "text": "\"Der knabbert an den kleinen Knochen rum, als wäre er ein Eichhörnchen!\"  2. Der knabbert an den Beinchen wie ein Eichkätzchen am letzten Körnchen!  3. Der nagt an den Knocherln wie ein Mäuslein am letzten Käsestück!"}]'::jsonb, ''),
  ('dem-tuad-ka-baa-mea-wee', 'Dem tuad ka Baa mea wee!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Dem tut kein Bein mehr weh!', '[{"kategorie": "wörtlich", "text": "\"Den zwickt kein Muskel mehr!\"  2. Der ist über den Jordan!  3. Der hat das Zeitliche gesegnet!  4. Der ist so tot wie ein Stein!"}]'::jsonb, ''),
  ('da-baanla-schneid-olle-knochn-ausn-fleisch-und-passd-auf-dass-meeglichst-weenich-valuan-geed', 'Da Baanla schneid olle Knochn ausn Fleisch und passd auf, dass meeglichst weenich valuan geed!', '', '', '', 'Wiener Fleischhauer-Slang', 'Der Beinler schneidet alle Knochen aus dem Fleisch und passt auf, dass möglichst wenig verloren geht!', '[{"kategorie": "wörtlich", "text": "\"Der Ausbeiner entfernt sämtliche Knochen aus dem Fleisch und achtet dabei auf einen möglichst geringen Verschnitt!\"  2. Der Fleischzerleger löst die Knochen präzise aus und minimiert dabei den Materialverlust!  3. Der Beinauslöser trennt das Fleisch sorgfältig vom Knochen und achtet dabei auf maximale Fleischausbeute!"}]'::jsonb, ''),
  ('i-suach-a-rechts-tiarl-beim-baanla-fian-ochtaneinzga-dreia', 'I suach a rechts Tiarl beim Baanla fian ochtaneinzga Dreia!', '', '', '', 'Wiener Mechaniker-Slang', 'Ich suche ein rechtes Türl beim Beinler für den 98-er Dreier!', '[{"kategorie": "wörtlich", "text": "\"Ich suche beim Schrotthändler eine rechte Türe für meinen 3-er BMW, Baujahr 1998\""}, {"kategorie": "", "text": "Ich benötige vom Autowrackverwerter eine rechte Beifahrertür für meinen alten 3er BMW (’98er)"}, {"kategorie": "", "text": "Suche beim Autometzker folgenden Ersatzteil: Rechte Seitentür für BMW 3er, E36, 1998"}]'::jsonb, ''),
  ('knochn-woan-friara-a-weatvolla-rooschdoff-den-de-baanlschdiara-aund-saaufnsiada-und-aund-laamsiada-vakaufd-haum', 'Knochn woan friara a weatvolla Rooschdoff, den de Baanlschdiara aund Saaufnsiada und aund Laamsiada vakaufd haum!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Knochen waren früher ein wertvoller Rohstoff, den die Gebeinestierer an die Seifen- und Leimsieder verkauft haben!', '[{"kategorie": "wörtlich", "text": "Knochen galten einst als wertvoller Rohstoff – die Knochensammler verkauften sie an Seifensieder und Leimsieder!\"  2. Knochen zählten einst zu den begehrten Rohstoffen und wurden von Knochensammlern an Seifen- und Leimhersteller weiterverkauft!  3. Tierknochen waren ein bedeutender Rohstoff im 18. und 19. Jahrhundert – sie wurden von den sogenannten \"Baanlstierern\" gesammelt und gegen Zahlung an die verarbeitenden Gewerke ausgeliefert!"}]'::jsonb, ''),
  ('oida-pass-auf-sunst-ziag-i-da-mein-baanlschdiara-duachd-rippaln', 'Oida, pass auf, sunst ziag I da mein Baanlschdiara duachd Rippaln!', '', '', '', 'Wiener Gaunersprache', 'Alter, pass auf, sonst zieh ich dir meinen Gebeinestierer durch die Ripperln!', '[{"kategorie": "wörtlich", "text": "\"Alter, pass auf, sonst zieh ich dir meinen Knochenstierer durch die Rippen!\"  2. Noch ein Mucks, Junge – und mein Feitel tanzt dir zwischen den Rippen!  3. Alter, spiel dich nicht - sonst fahr ich dir mit meinem Knochenkratzer zwischen die Rippen!"}]'::jsonb, ''),
  ('mei-oma-hod-friara-aus-a-poa-suppnbaana-a-gaunzes-essn-zaubad', 'Mei Oma hod friara aus a poa Suppnbaana a gaunzes Essn zaubad!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Meine Oma hat früher aus ein paar Suppenbeinen ein ganzes Essen gezaubert!', '[{"kategorie": "wörtlich", "text": "\"Meine Großmutter hat früher aus ein paar Suppenknochen eine ganze Mahlzeit gezaubert!\"  2. Meine Oma hat früher mit ein paar Suppenknochen die ganze Familie satt gemacht!  3. Aus ein paar Knocherln, die andere weggeschmissen hätten, hat meine Großmutter früher ein ganzes Mittagessen gezaubert!"}]'::jsonb, ''),
  ('wia-ma-da-dokta-es-abszess-aufscghniidn-hod-is-a-lita-goeoewe-baatz-aussegrunna', 'Wia ma da Dokta es Abszess aufscghniidn hod, is a Lita gööwe Baatz aussegrunna!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Wie mir der Doktor das Abszess aufgeschnitten hat, ist ein Liter gelbe Batz herausgeronnen!', '[{"kategorie": "wörtlich", "text": "\"Als mir der Arzt den Abszess aufgeschnitten hat, ist ein Liter gelber Eiter rausgeronnen!\"   2. Nachdem der Arzt den Abszess geöffnet hat, ist der Eiter rausgeschossen wie Senf aus ''ner alten Tube!  3. Nach dem Schnitt ist eine Riesenmenge gelblich-grüner Flüssigkeit aus dem Abszess geronnen - fast ein ganzer Becher voll!"}]'::jsonb, ''),
  ('nooch-drei-toog-dauareeng-brauchsd-jetzt-gummischdiifaen-waeu-draussd-schdeesd-sunst-bis-zud-knia-in-da-baatz', 'Nooch drei Toog Dauareeng brauchsd jetzt Gummischdiifän - wäu draussd schdeesd sunst bis zud Knia in da Baatz!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach drei Tagen Dauerregen brauchst du jetzt Gummistiefeln - weil draußen stehst du sonst bis zu den Knien in der Batz!', '[{"kategorie": "wörtlich", "text": "\"Nach dem Dauerregen kannst du ohne Gummistiefel nicht mehr raus – draußen steht der Matsch knöcheltief!\"  2. Drei Tage Regen und der Boden ist komplett aufgeweicht – ohne Gummistiefel versinkst du draußen knietief im Schlamm!  3. Nach tagelangem Regen hat sich der Boden in einen Sumpf verwandelt - da brauchst du Gummistiefeln, sonst bleibst du im Gatsch stecken!"}]'::jsonb, ''),
  ('de-foroeoen-hauma-iwad-nocht-baatzd-mit-knoofae-lemoni-und-kimmae', 'De Foröön hauma iwad Nocht baatzd - mit Knoofä, Lemoni und Kimmä!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Forelle haben wir über Nacht gebatzt – mit Knoblauch, Limone und Kümmel!', '[{"kategorie": "wörtlich", "text": "\"Die Forelle haben wir über Nacht mit einer Beize aromatisiert – mit Knoblauch, Zitronensaft und Kümmel!\"  2. Die Forelle haben wir über Nacht in einer Beize mit Knoblauch, Zitrone und Kümmel mariniert!  3. Die Forelle haben wir über Nacht in einer würzigen Marinade eingelegt – mit Knoblauch, Zitronensaft und Kümmel!"}]'::jsonb, ''),
  ('baatz-ma-si-a-wengl', 'Baatz ma si a wengl!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Baatzen wir uns ein wenig!', '[{"kategorie": "wörtlich", "text": "\"Ruhen wir uns ein wenig aus!\"  2. Lasst uns ein wenig entspannen!  3. Lassen wir die Seele ein wenig baumeln!"}]'::jsonb, ''),
  ('recht-in-da-baatz-sei', 'recht in da Baatz sei', '', '', '', 'Wiener Gaunersprache', 'recht in der Baatz sein', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"tief in der Beize eingelegt sein\""}, {"kategorie": "fig.", "text": "\"tief in der Patsche sitzen\""}, {"kategorie": "", "text": "\"bauchtief im Schlamassel stecken\""}, {"kategorie": "", "text": "\"voll in der Scheiße hängen\""}]'::jsonb, 'Jetzd samma recht in da Baatz - woi ma beedn oda schmiian?'),
  ('jetzd-samma-recht-in-da-baatz-woi-ma-beedn-oda-schmiian', 'Jetzd samma recht in da Baatz - woi ma beedn oda schmiian?', '', '', '', 'Wiener Gaunersprache', 'Jetzt sind wir tief in der Beize - wollen wir beten oder schmieren?', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Jetzt stecken wir bauchtief im Schlamassel - da hilft nur beten oder bestechen!\"  2. Wir hängen voll in der Scheiße – jetzt geht nur noch: Hände falten oder Scheine falten!  3. Jetzt stecken wir bis zum Hals in der Scheiße – entweder beten oder buttern!"}]'::jsonb, 'recht in da Baatz sei'),
  ('wem-in-da-baatz-haum', 'wem in da Baatz haum', '', '', '', 'Wiener Gaunersprache', 'jemanden in der Baatz haben', '[{"kategorie": "wörtlich, Gaunersprache", "text": "\"jemanden in der Beize eingelegt haben\""}, {"kategorie": "fig.", "text": "jemanden in der [[Mangel]] haben"}, {"kategorie": "", "text": "\"jemanden am Wickel haben\"  4. jemanden [[in]] der Reißen haben"}]'::jsonb, 'De haum eam in da Baatz - I hoff, ea hoid dicht!'),
  ('de-haum-eam-in-da-baatz-i-hoff-ea-hoid-dicht', 'De haum eam in da Baatz - I hoff, ea hoid dicht!', '', '', '', 'Wiener Gaunersprache', 'Die haben ihn in der Beize [konserviert] - ich hoffe, er hält dicht!', '[{"kategorie": "wörtlich, Gaunerjargon", "text": "\"Die haben ihn in der Mangel - ich hoffe, er hält dicht!\"  2. Die nehmen ihn gerade ordentlich auseinander – hoffentlich bleibt er standhaft!  3. Die kochen ihn grad schön weich – mal sehen, ob er bissfest bleibt!"}]'::jsonb, 'wem in da Baatz haum'),
  ('reib-ma-noo-a-priisal-von-dein-baatzdn-ume-dea-geed-duach-bis-ins-hiankaastl', 'Reib ma noo a Priisal von dein Baatzdn ume - dea geed duach bis ins Hiankaastl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Reib mir noch ein Priserl von deinem Batzten rüber – der geht durch bis ins Hirnkastl!', '[{"kategorie": "wörtlich", "text": "\"Gib mir noch eine Prise von deinem Schnupftabak – der geht direkt bis ins Hirn durch!\"  2. Lass mich noch eine Prise von deinem Tabak schnupfen – der fährt einem so richtig ins Hirn!  3. Gib mir noch eine Nase voll – dieser Schnupftabak von dir pustet mir den Schädel endlich frei!"}]'::jsonb, ''),
  ('waunns-an-schwoazbaatzdn-haedn-schnupfatnsn', 'Waunns an Schwoazbaatzdn hädn, schnupfatnsn?', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Wenn Sie einen Schwarzgebeizten hätten, schnupferten Sie ihn?', '[{"kategorie": "wörtlich", "text": "\"Wenn Sie einen schwarzgebeizten Schnupftabak hätten, würden Sie ihn schnupfen?\"  (Zur Beachtung: Dieser Zungenbrecher wird gerne als Testphrase zur Bewertung der wienerischen Aussprache herangezogen - wer diesen Zungenbrecher richtig ausspricht, kann von sich mit Stolz behaupten, das Wienerische perfekt zu beherrschen)"}, {"kategorie": "", "text": "Wenn Sie den Schwarzgebeizten hätten – würden Sie ihn sich reinziehen?  3. Ein feuchter Schwarzer in der Dose – da kitzelt’s Ihnen doch schon in der Nase, oder?"}]'::jsonb, ''),
  ('des-risotto-woa-baatzwaach-waunn-i-gatsch-fressn-muass-gee-i-des-naechste-moi-in-goatn', 'Des Risotto woa baatzwaach - waunn I Gatsch fressn muass, gee I des nächste Moi in Goatn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Das Risotto war batzweich - wenn ich Gatsch fressen muss, geh'' ich das nächste Mal in den Garten!', '[{"kategorie": "wörtlich", "text": "\"Das Risotto war so schlabbrig und durchgeweicht - da hätt'' ich gleich ''nen Kübel Gatsch mit Parmesan bestellen können!\"  2. Wenn ich so ''nen Matsch in der Schüssel will, fress ich das nächste Mal den Schlamm direkt vom Gartenweg!  3. Wenn ich auf Babykost steh, geh ich ins Altersheim – und nicht ins Beisl auf ein Risotto!"}]'::jsonb, ''),
  ('si-hod-a-baatzwaachs-herz', 'Si hod a baatzwaachs Herz!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie hat ein batzweiches Herz!', '[{"kategorie": "wörtlich", "text": "\"Sie hat ein Herz so weich wie Butter\""}, {"kategorie": "", "text": "Sie hat ein Herz aus Samt!  3. Ihr Herz ist wie Wachs!"}]'::jsonb, ''),
  ('baatzwaach-in-da-bian-sei', 'baatzwaach in da Bian sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'batzweich in der Birne sein', '[{"kategorie": "wörtlich", "text": "\"im Hirn weichgekocht sein\", \"dünnhäutig sein\", \"eine weiche Schale und kein Rückgrat haben\", \"psychisch nicht belastbar sein\", \"geistig auf Watte gebettet sein\""}, {"kategorie": "scherzhaft für", "text": "\"ein weich gesoffenes Hirn haben\", \"einen Vollrausch haben\", [[blaadlwaach]] sei"}]'::jsonb, ''),
  ('dea-hoid-goa-nix-aus-dea-is-baatzwaach-in-da-bian', 'Dea hoid goa nix aus - dea is baatzwaach in da Bian!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der hält gar nichts aus – der ist batzweich in der Birne!', '[{"kategorie": "wörtlich", "text": "\"Der steckt nichts weg – der ist total weich in der Birne!\"  2. Der ist mental so labil, da reicht ein schiefer Blick und er bricht zusammen!  3. Der kann mit Druck null umgehen – weich wie Watte im Kopf!"}]'::jsonb, 'baatzwaach in da Bian sei'),
  ('dea-is-so-baatzwaach-in-da-bian-dea-brauchd-boid-an-rollatoa-fias-hian', 'Dea is so baatzwaach in da Bian - dea brauchd boid an Rollatoa fias Hian!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der ist so batzweich in der Birne - der braucht bald einen Rollator fürs Hirn!', '[{"kategorie": "wörtlich", "text": "\"Der hat sich so weich gesoffen - der braucht bald eine Windel fürs Hirn!\"  2. Der ist so weichgesoffen - dem rinnt das Hirn bald aus den Ohren!  3. Der hat sich sein Hirn batzweich gesoffen - der braucht bald eine Saugleitung zum Nachdenken!"}]'::jsonb, 'baatzwaach in da Bian sei'),
  ('a-baatzwaacha-schnaeae', 'a baatzwaacha Schnää', '', '', '', 'Wiener Sprüche, die sitzen!', 'ein batzweicher Schnee', '[{"kategorie": "wörtlich", "text": "\"ein Schnee so matschig-weich wie Brei\""}, {"kategorie": "allg.", "text": "extrem weicher Pappschnee (aufgrund von Regen und höheren Temperaturen extrem matschiger Schnee), Sulzschnee,  Firnschnee"}]'::jsonb, 'Do untn woas echt zaach - nua noo baatzwaacha Schnää, do bist gfoan wiara bsoffane Foröön!'),
  ('do-untn-woas-echt-zaach-nua-noo-baatzwaacha-schnaeae-do-bist-gfoan-wiara-bsoffane-foroeoen', 'Do untn woas echt zaach - nua noo baatzwaacha Schnää, do bist gfoan wiara bsoffane Foröön!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Da unten war’s echt zäh – nur noch batzweicher Schnee, da du bist gefahren wie in ''ne besoffene Forelle!', '[{"kategorie": "wörtlich", "text": "\"Unten war’s ein einziger Kampf – nur noch batzweicher Schnee, da bist du gefahren wie durch Haferschleim!\"  2. Da unten war''s brutal - der Schnee war nur noch eine einzige Sulz, da bist du eingesunken wie in Wackelpudding!  3. Unten war die Piste nur noch eine einzige Matschbahn – da bist du geschwommen wie eine besoffene Forelle!"}]'::jsonb, 'a baatzwaacha Schnää'),
